class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        first, last = {}, {}
        for i, ch in enumerate(s):
            if ch not in first:
                first[ch] = i
            last[ch] = i

        intervals = []
        for c in first:
            l, r = first[c], last[c]
            j = l
            ok = True
            while j <= r:
                ch = s[j]
                if first[ch] < l:      # a character inside also appears before l
                    ok = False
                    break
                if last[ch] > r:
                    r = last[ch]
                j += 1
            if ok and not (l == 0 and r == n - 1):
                intervals.append((r, l))

        # interval scheduling: maximum number of disjoint intervals
        intervals.sort()
        count = 0
        end = -1
        for r, l in intervals:
            if l > end:
                count += 1
                end = r
        return count >= k
